import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
  compoundReveal,
  inOutEnvelope,
} from "../motion";
import { BRAND } from "@/lib/brand";

export const fps = 25;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const TRANSITION = 15;

// ============================================================
// CHECKMARK ICON
// ============================================================
const CheckIcon: React.FC<{ size: number; progress: number }> = ({
  size,
  progress,
}) => {
  const dashLen = 60;
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 60 60"
      style={{ flexShrink: 0, overflow: "visible" }}
    >
      <circle
        cx={30}
        cy={30}
        r={28}
        fill={COLORS.orangeTint}
        opacity={progress}
        style={{
          transformOrigin: "30px 30px",
          transform: `scale(${interpolate(progress, [0, 1], [0.6, 1])})`,
        }}
      />
      <circle
        cx={30}
        cy={30}
        r={28}
        fill="none"
        stroke={COLORS.orange}
        strokeWidth={1.5}
        opacity={progress * 0.7}
      />
      <path
        d="M16 31 L26 41 L45 21"
        stroke={COLORS.orange}
        strokeWidth={5}
        strokeLinecap="round"
        strokeLinejoin="round"
        fill="none"
        strokeDasharray={dashLen}
        strokeDashoffset={interpolate(progress, [0, 1], [dashLen, 0], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        })}
      />
    </svg>
  );
};

// ============================================================
// SCENE: CHECKMARK LIST (transparent bg)
// ============================================================
const ITEMS = [
  "No more API keys",
  "No more account creation",
  "No more credit cards",
  "No more billing complexity",
];

const SceneListDuration = 220;

const SceneList: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  const envelope = inOutEnvelope(frame, vfps, SceneListDuration);

  const titleIn = springIn(frame, vfps, TIMING.entrance, "SNAPPY");
  const highlightIn = springIn(frame, vfps, TIMING.entrance + 12, "LIQUID");

  const titleDrift = ambientDrift(frame, 2, 95, "list-title");

  const headlineSize = base * 0.062;
  const itemSize = base * 0.04;

  const cardIn = springIn(frame, vfps, TIMING.entrance + 8, "LIQUID");

  return (
    <AbsoluteFill style={{ opacity: envelope }}>
      <div
        style={{
          position: "absolute",
          left: "9%",
          right: "9%",
          top: "16%",
          bottom: "14%",
          display: "flex",
          flexDirection: "column",
          gap: base * 0.05,
        }}
      >
        {/* Headline */}
        <div
          style={{
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontWeight: 700,
            fontSize: headlineSize,
            color: COLORS.text,
            letterSpacing: "-0.025em",
            lineHeight: 1.05,
            maxWidth: "85%",
            opacity: titleIn,
            transform: `translateY(${interpolate(titleIn, [0, 1], [28, 0])}px) translateY(${titleDrift}px)`,
            filter: `blur(${interpolate(titleIn, [0, 1], [5, 0])}px)`,
          }}
        >
          {" "}
          <span
            style={{
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              background: COLORS.orangeTint,
              borderBottom: `${Math.max(2, base * 0.003)}px solid ${COLORS.orange}`,
              padding: `0 ${base * 0.012}px`,
              borderRadius: base * 0.008,
              color: COLORS.text,
              clipPath: `inset(0 ${interpolate(highlightIn, [0, 1], [100, 0])}% 0 0)`,
            }}
          >

          </span>
        </div>

        {/* Checklist — no card surface, fully transparent backdrop */}
        <div
          style={{
            marginTop: base * 0.015,
            display: "flex",
            flexDirection: "column",
            gap: base * 0.042,
            opacity: cardIn,
            transform: `translateY(${interpolate(cardIn, [0, 1], [40, 0])}px)`,
          }}
        >
          {ITEMS.map((label, i) => {
            const baseDelay = TIMING.entrance + 24;
            const stagger = 14;
            const itemIn = staggeredSpring(
              frame,
              vfps,
              i,
              baseDelay,
              stagger,
              i % 2 === 0 ? "SNAPPY" : "ELASTIC",
            );
            const itemDriftY = ambientDrift(
              frame,
              1.5,
              80 + i * 17,
              `item-${i}`,
            );

            return (
              <div
                key={i}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: base * 0.03,
                  opacity: itemIn,
                  transform: `translateX(${interpolate(itemIn, [0, 1], [-base * 0.04, 0])}px) translateY(${itemDriftY}px)`,
                }}
              >
                <CheckIcon size={base * 0.065} progress={itemIn} />
                <div
                  style={{
                    fontFamily: "'GT Walsheim', Inter, sans-serif",
                    fontWeight: 600,
                    fontSize: itemSize,
                    color: COLORS.text,
                    letterSpacing: "-0.01em",
                    lineHeight: 1.15,
                  }}
                >
                  {label}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ============================================================
// MAIN COMPOSITION
// ============================================================
export const durationInFrames = SceneListDuration;

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={SceneListDuration}>
        <SceneList />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
